// Standalone REST backend generated by PHANTOM. Zero runtime dependencies: node:http + node:sqlite.
// It does not contact PHANTOM; everything it needs is in this folder.
import { createServer } from 'node:http';
import type { IncomingMessage, ServerResponse } from 'node:http';
import { existsSync, mkdirSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { BUILD_ID, RESOURCES } from './resources.ts';
import { Store } from './store.ts';
import type { StoredRecord } from './store.ts';
import { validateBody } from './validate.ts';
import type { JsonObject, JsonValue } from './validate.ts';

const PORT = Number(process.env.PORT ?? 8788);
const HOST = process.env.HOST ?? '127.0.0.1';
const DATA_DIR = resolve(process.env.DATA_DIR ?? 'data');
const SEED_FILE = process.env.SEED_FILE;
const MAX_BODY_BYTES = Number(process.env.MAX_BODY_BYTES ?? 1_048_576);
const CORS_ORIGINS = new Set(
  (process.env.CORS_ORIGINS ?? 'http://127.0.0.1:8787,http://localhost:8787,http://127.0.0.1:5173,http://localhost:5173')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean),
);

const RESOURCE_NAME = /^[a-z][a-z0-9_-]{0,39}$/;
const SERVER_FIELDS = new Set(['id', 'createdAt', 'updatedAt', '__proto__']);
const RESOURCE_NAMES = Object.keys(RESOURCES).filter((r) => RESOURCE_NAME.test(r));

mkdirSync(DATA_DIR, { recursive: true });
const DB_FILE = resolve(DATA_DIR, 'phantom.db');
const store = new Store(DB_FILE, RESOURCE_NAMES);
const startedAt = Date.now();

interface Reply {
  status: number;
  body?: JsonValue;
  headers?: Record<string, string>;
}

const err = (status: number, error: string, message: string, extra: JsonObject = {}): Reply => ({ status, body: { error, message, ...extra } });

function importSeed(file: string): number {
  const seed = JSON.parse(readFileSync(file, 'utf8')) as { collections?: Record<string, StoredRecord[]> };
  let imported = 0;
  store.transaction(() => {
    for (const resource of RESOURCE_NAMES) {
      const records = seed.collections?.[resource];
      if (!Array.isArray(records)) continue;
      for (const r of records) {
        if (!Number.isInteger(r.id) || r.id < 1) continue;
        store.importRecord(resource, r);
        imported++;
      }
    }
  });
  return imported;
}

if (SEED_FILE && existsSync(SEED_FILE) && RESOURCE_NAMES.every((r) => store.count(r) === 0)) {
  const n = importSeed(SEED_FILE);
  console.log(`[phantom-generated] imported ${n} seed record(s) from ${SEED_FILE}`);
}

function parseBody(raw: string): { ok: true; value: JsonObject } | { ok: false; reply: Reply } {
  if (raw.trim() === '') return { ok: false, reply: err(400, 'invalid_body', 'Request body must be a JSON object') };
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    return { ok: false, reply: err(400, 'invalid_json', 'Request body is not valid JSON') };
  }
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return { ok: false, reply: err(400, 'invalid_body', 'Request body must be a JSON object') };
  }
  const out: JsonObject = {};
  for (const [k, v] of Object.entries(value as JsonObject)) if (!SERVER_FIELDS.has(k)) out[k] = v;
  return { ok: true, value: out };
}

function matchesFilters(record: StoredRecord, query: URLSearchParams): boolean {
  for (const [k, v] of query) {
    const field = Object.hasOwn(record, k) ? record[k] : undefined;
    if (field === undefined) return false;
    if (field === null) {
      if (v !== 'null') return false;
    } else if (typeof field === 'object' || String(field) !== v) return false;
  }
  return true;
}

function userFields(record: StoredRecord): JsonObject {
  const { id: _id, createdAt: _c, updatedAt: _u, ...data } = record;
  return data;
}

function route(method: string, pathname: string, query: URLSearchParams, raw: string): Reply {
  if (pathname === '/health' && method === 'GET') {
    const counts: Record<string, number> = {};
    for (const r of RESOURCE_NAMES) counts[r] = store.count(r);
    return {
      status: 200,
      body: { status: 'ok', service: 'phantom-generated-backend', buildId: BUILD_ID, pid: process.pid, storage: 'sqlite', database: DB_FILE, uptimeSeconds: Math.round((Date.now() - startedAt) / 1000), records: counts },
    };
  }
  const segments = pathname.replace(/\/+$/, '').split('/').slice(1);
  if (segments[0] !== 'api' || segments.length < 2 || segments.length > 3) {
    return err(404, 'unsupported_route', 'This backend serves /api/:resource and /api/:resource/:id only');
  }
  const resource = segments[1];
  if (!RESOURCE_NAME.test(resource)) return err(404, 'unsupported_route', 'Resource names must match ^[a-z][a-z0-9_-]{0,39}$');
  if (!RESOURCE_NAMES.includes(resource)) return err(404, 'unknown_resource', `Resource ${resource} is not part of the generated contract`);
  const schema = RESOURCES[resource];

  if (segments.length === 2) {
    if (method === 'GET') return { status: 200, body: store.list(resource).filter((r) => matchesFilters(r, query)) };
    if (method === 'POST') {
      const body = parseBody(raw);
      if (!body.ok) return body.reply;
      const problems = validateBody(body.value, schema, 'create');
      if (problems.length) return err(400, 'validation_failed', 'Body does not match the inferred contract', { details: problems });
      const created = store.insert(resource, body.value, new Date().toISOString());
      return { status: 201, body: created, headers: { location: `/api/${resource}/${created.id}` } };
    }
    return { ...err(405, 'method_not_allowed', 'Allowed methods: GET, POST'), headers: { allow: 'GET, POST' } };
  }

  if (!['GET', 'PATCH', 'PUT', 'DELETE'].includes(method)) {
    return { ...err(405, 'method_not_allowed', 'Allowed methods: GET, PATCH, PUT, DELETE'), headers: { allow: 'GET, PATCH, PUT, DELETE' } };
  }
  let patch: JsonObject | undefined;
  if (method === 'PATCH' || method === 'PUT') {
    const body = parseBody(raw);
    if (!body.ok) return body.reply;
    const problems = validateBody(body.value, schema, method === 'PUT' ? 'replace' : 'patch');
    if (problems.length) return err(400, 'validation_failed', 'Body does not match the inferred contract', { details: problems });
    patch = body.value;
  }
  const id = /^[1-9][0-9]{0,15}$/.test(segments[2]) ? Number(segments[2]) : undefined;
  const existing = id === undefined ? undefined : store.get(resource, id);
  if (!existing) return err(404, 'not_found', `${resource} record not found`);

  if (method === 'GET') return { status: 200, body: existing };
  if (method === 'DELETE') {
    store.delete(resource, existing.id);
    return { status: 204 };
  }
  const merged = method === 'PATCH' ? { ...userFields(existing), ...patch } : { ...patch };
  const updated = store.update(resource, existing.id, merged, new Date().toISOString());
  return updated ? { status: 200, body: updated } : err(404, 'not_found', `${resource} record not found`);
}

function applyCors(req: IncomingMessage, res: ServerResponse): void {
  const origin = req.headers.origin;
  if (origin && CORS_ORIGINS.has(origin)) {
    res.setHeader('access-control-allow-origin', origin);
    res.setHeader('vary', 'Origin');
    res.setHeader('access-control-allow-methods', 'GET, POST, PATCH, PUT, DELETE, OPTIONS');
    res.setHeader('access-control-allow-headers', 'content-type');
    res.setHeader('access-control-expose-headers', 'location, x-phantom-generated-build');
  }
}

function send(res: ServerResponse, reply: Reply): void {
  res.setHeader('x-phantom-generated-build', BUILD_ID);
  for (const [k, v] of Object.entries(reply.headers ?? {})) res.setHeader(k, v);
  if (reply.status === 204 || reply.body === undefined) {
    res.writeHead(reply.status).end();
    return;
  }
  res.writeHead(reply.status, { 'content-type': 'application/json; charset=utf-8' }).end(JSON.stringify(reply.body));
}

const server = createServer((req, res) => {
  applyCors(req, res);
  const method = (req.method ?? 'GET').toUpperCase();
  if (method === 'OPTIONS') {
    res.writeHead(204).end();
    return;
  }
  const url = new URL(req.url ?? '/', 'http://localhost');
  const chunks: Buffer[] = [];
  let size = 0;
  let tooLarge = false;
  req.on('data', (chunk: Buffer) => {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) tooLarge = true;
    else chunks.push(chunk);
  });
  req.on('end', () => {
    if (tooLarge) return send(res, err(413, 'payload_too_large', `Request body exceeds ${MAX_BODY_BYTES} bytes`));
    try {
      send(res, route(method, url.pathname, url.searchParams, Buffer.concat(chunks).toString('utf8')));
    } catch (e) {
      console.error('[phantom-generated] unhandled error', e);
      send(res, err(500, 'internal_error', 'Unexpected server error'));
    }
  });
});

server.listen(PORT, HOST, () => {
  const address = server.address();
  const port = typeof address === 'object' && address ? address.port : PORT;
  // Machine-readable line used by tooling that starts this server on an ephemeral port.
  console.log(`PHANTOM_GENERATED_LISTENING port=${port}`);
  console.log(`[phantom-generated] build ${BUILD_ID} serving ${RESOURCE_NAMES.join(', ') || '(no resources)'} on http://${HOST}:${port} (sqlite: ${DB_FILE})`);
});

function shutdown(): void {
  server.close();
  store.close();
  process.exit(0);
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
